  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/shell/styles.css FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/shell/ui.tsx FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/shell/view-menu.css FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/shell/view-menu.tsx FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/shell/viz.tsx FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/source.json FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/sql/blocks/plan.sql FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/sql/blocks/probes.sql FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/sql/blocks/profile_targets.sql FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/sql/blocks/settings_extra.sql FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/sql/blocks/success_criteria.sql FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/sql/blocks/teardown_extra.sql FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/src/main.tsx FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/streamlit_app.py FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, REPLACE('COPY INTO @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/vite.config.ts FROM (SELECT BASE64_DECODE_STRING('''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE', '__TARGET__', :tgt));
  stmts := ARRAY_APPEND(:stmts, 'COPY FILES INTO @' || :tgt || '.APP_STAGE/releases/3f1ad1a9f907612d/ FROM @' || :tgt || '.APP_STAGE/source/3f1ad1a9f907612d/ FILES=(''.streamlit/config.toml'',''assets/app.js'',''assets/style.css'',''environment.yml'',''runtime_config.json'',''streamlit_app.py'')');
  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''CDCMIRROR_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''CDCMIRROR_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''CDCMIRROR_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''CDCMIRROR_APP'' AND "comment" IN (''oneshot-source:29_cdc_mirror_cost'',''CDC Mirror Cost Ranking and Serving Bake-off — generated from account discovery'',''Observability Monitor - generated from account discovery'') AND "owner"=CURRENT_ROLE(); IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.CDCMIRROR_APP FROM ''@__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:29_cdc_mirror_cost''; ALTER STREAMLIT __TARGET__.CDCMIRROR_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
  stmts := ARRAY_APPEND(:stmts, REPLACE('BEGIN DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20071,''ONESHOT_SOURCE belongs to a different installation''); BEGIN SHOW WORKSPACES LIKE ''ONESHOT_SOURCE'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ONESHOT_SOURCE''; IF (:present_count>0) THEN SHOW WORKSPACES LIKE ''ONESHOT_SOURCE'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ONESHOT_SOURCE'' AND "comment"=''oneshot-source:29_cdc_mirror_cost'' AND "owner"=CURRENT_ROLE(); IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE WORKSPACE __TARGET__.ONESHOT_SOURCE COMMENT=''oneshot-source:29_cdc_mirror_cost''; ALTER WORKSPACE __TARGET__.ONESHOT_SOURCE ADD LIVE VERSION FROM LAST; COPY FILES INTO ''snow://workspace/__TARGET__.ONESHOT_SOURCE/versions/live/'' FROM @__TARGET__.APP_STAGE/source/3f1ad1a9f907612d/; END IF; END; EXCEPTION WHEN OTHER THEN RETURN ''SOURCE_WORKSPACE_FAILED: '' || SQLERRM; END', '__TARGET__', :tgt));
  notes := ARRAY_APPEND(:notes, 'Editable source: ' || :tgt || '.ONESHOT_SOURCE. Existing workspace and app source are preserved on rerun.');
  notes := ARRAY_APPEND(:notes, 'OPEN THE APP after building: Snowsight > Projects > Streamlit > CDCMIRROR_APP');
  cost_day := :cost_day + 0.10;
  cost_detail := ARRAY_APPEND(:cost_detail, 'Streamlit use is projected at 0.10 credits/day for light XS usage; source copying has additional serverless charges.');

        WHILE (:statement_index<ARRAY_SIZE(:stmts)) DO
          LET app_statement VARCHAR := :stmts[:statement_index]::VARCHAR;
          EXECUTE IMMEDIATE :app_statement;
          LET app_statement_result VARCHAR := (SELECT $1::VARCHAR FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) LIMIT 1);
          IF (STARTSWITH(:app_statement_result,'SOURCE_WORKSPACE_FAILED:')) THEN
            source_error := :app_statement_result;
          END IF;
          statement_index := :statement_index+1;
        END WHILE;
      ELSEIF (:existing_app[0]:comment::VARCHAR NOT IN ('oneshot-source:29_cdc_mirror_cost','CDC Mirror Cost Ranking and Serving Bake-off — generated from account discovery','Observability Monitor - generated from account discovery')) THEN
        completion_error := 'Existing app has an unrelated identity; its source was preserved.';
      END IF;
      IF (:completion_error='') THEN
        EXECUTE IMMEDIATE 'SHOW STREAMLITS IN SCHEMA ' || :tgt;
        app_ready := (SELECT COUNT(*)=1 FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"='CDCMIRROR_APP');
        IF (:app_ready) THEN
          app_url := 'https://app.snowflake.com/' || LOWER(CURRENT_ORGANIZATION_NAME()) || '/' || LOWER(CURRENT_ACCOUNT_NAME()) || '/#/streamlit-apps/' || :tgt || '.CDCMIRROR_APP';
          completion_status := IFF(:prior_result[0]:STATUS::VARCHAR='READY' AND COALESCE(:source_report:status::VARCHAR,'UNAVAILABLE') IN ('AVAILABLE','REVIEW_SOURCE_PROPOSAL','DISCOVERY_COMPLETE','AI_ASSISTED_SIGNAL_DISCOVERY'),'READY','APP_READY_REVIEW_REQUIRED');
          BEGIN
            EXECUTE IMMEDIATE 'SHOW WORKSPACES IN SCHEMA ' || :tgt;
            LET source_exists BOOLEAN := (SELECT COUNT(*)=1 FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"='ONESHOT_SOURCE' AND "comment"='oneshot-source:29_cdc_mirror_cost' AND "owner"=CURRENT_ROLE());
            IF (:source_exists AND :source_error='') THEN
              source_url := 'https://app.snowflake.com/' || LOWER(CURRENT_ORGANIZATION_NAME()) || '/' || LOWER(CURRENT_ACCOUNT_NAME()) || '/#/workspaces/ws/' || :db || '/' || :sch || '/ONESHOT_SOURCE/streamlit_app.py';
              source_status := 'AVAILABLE';
            ELSE
              source_status := 'SOURCE_WORKSPACE_UNAVAILABLE';
              source_error := COALESCE(NULLIF(:source_error,''),'The app is installed, but its editable source workspace was not verified. Check CREATE WORKSPACE privileges or a conflicting workspace identity. The original source remains on APP_STAGE.');
            END IF;
          EXCEPTION WHEN OTHER THEN
            source_status := 'SOURCE_WORKSPACE_UNAVAILABLE';
            source_error := SQLERRM;
          END;
        END IF;
      END IF;
      LET receipt_json VARCHAR := TO_JSON(:prior_result);
      LET discovery_json VARCHAR := TO_JSON(:source_report);
      LET persist_query VARCHAR := 'MERGE INTO ' || :tgt || '.INSTALLATION_STATUS target USING (SELECT 1 ID,? STATUS,PARSE_JSON(?) DETAILS,PARSE_JSON(?) DISCOVERY) source ON target.ID=source.ID WHEN MATCHED THEN UPDATE SET STATUS=source.STATUS,DETAILS=source.DETAILS,DISCOVERY=source.DISCOVERY,UPDATED_AT=CURRENT_TIMESTAMP() WHEN NOT MATCHED THEN INSERT VALUES(source.ID,source.STATUS,source.DETAILS,source.DISCOVERY,CURRENT_TIMESTAMP())';
      EXECUTE IMMEDIATE :persist_query USING(completion_status,receipt_json,discovery_json);
    END IF;
  EXCEPTION WHEN OTHER THEN
    completion_error := SQLERRM;
  END;
  result_rows := (SELECT IFF(:app_ready,:completion_status,'APP_BUILD_FAILED') AS STATUS,:app_url AS OPEN_APP_URL,
    :source_url AS EDIT_SOURCE_URL,:source_status AS SOURCE_STATUS,:source_error AS SOURCE_ERROR,
    IFF(:app_ready,'OPEN THE APP: click OPEN_APP_URL.' || IFF(:completion_status='READY',' No variable changes are required.',' The existing app is installed; review its discovery/build status before using incomplete results.'),'App installation failed: ' || :completion_error) AS NEXT_ACTION,
    :source_report:status::VARCHAR AS DISCOVERY_STATUS,:completion_error AS ERROR,:prior_result AS BUILD_DETAILS);
  RETURN TABLE(result_rows);
END;
$$;
